"""
Parser for SOAP trace files (SOAPMessageTrace format).

Uses ru_soap (xsdata-generated classes from ru_soap.xsd). Each Envelope is
parsed with xsdata; SOAPRecord wraps it and exposes flat access (.get,
.body_tag) and typed access (.header(), .body(), .managed_objects()).

Files: root <SOAPMessageTrace>, sequence of <UTC-Timestamp> + <SOAP-ENV:Envelope>.
Body: parValueChangeInd, moduleReadyInd, modifyParameterReq with managedObject, parameter.

Example:
    from taf.ul.oam_kpi_calculations.parsers.soap.parser import (
        SOAPParser,
        SOAPRecord,
        get_header_from_envelope,
        get_managed_objects_from_envelope,
        matches_param_transition,
    )
    parser = SOAPParser("path/to/file.xml")
    for record in parser.records():
        print(record.timestamp_str, record.body_tag)
        print(record.get("frameNumber"), record.get_prev("frameNumber"))
        h = record.header()
        if h:
            print(h.action, h.from_value, h.to)
        for mo in record.managed_objects():
            print(mo.class_value, mo.dist_name, mo.parameter)
"""
from __future__ import annotations

import xml.etree.ElementTree as ET
from datetime import datetime
from pathlib import Path

from xsdata.formats.dataclass.parsers import XmlParser
from xsdata.formats.dataclass.parsers.config import ParserConfig

from xsdata.exceptions import XmlContextError

from taf.ul.oam_kpi_calculations.parsers.soap.ru_soap import (
    BodyType,
    Envelope,
    HeaderType,
    ManagedObjectType,
    ModifyParameterReqType,
    ModuleReadyIndType,
    ParValueChangeIndType,
    ParameterType,
)

_xsdata_config = ParserConfig()
_xsdata_parser = XmlParser(config=_xsdata_config)

SOAP_ENV_NS = "http://schemas.xmlsoap.org/soap/envelope/"


def _parse_header_from_et(header_elem: ET.Element) -> HeaderType:
    """Build HeaderType from ET Header element (action, from, to)."""
    action = from_val = to = None
    for child in header_elem:
        local = _local_tag(child)
        text = _elem_text(child)
        if local == "action":
            action = text or None
        elif local == "from":
            from_val = text or None
        elif local == "to":
            to = text or None
    return HeaderType(action=action, from_value=from_val, to=to)


def _strip_header_from_envelope_element(env_elem: ET.Element) -> None:
    """Remove Header child from Envelope element in-place so xsdata only sees Body.
    Avoids 'Primitive node doesn't support child nodes' on Header content."""
    for child in list(env_elem):
        local = child.tag.split("}", 1)[-1] if child.tag and "}" in child.tag else (child.tag or "")
        if local == "Header":
            env_elem.remove(child)
            break


def _local_tag(elem: ET.Element) -> str:
    """Local part of tag (no namespace)."""
    tag = elem.tag or ""
    return tag.split("}", 1)[-1] if "}" in tag else tag


def _elem_text(elem: ET.Element) -> str:
    """Direct text content of element (ignores nested elements)."""
    return (elem.text or "").strip()


def _parse_managed_object_from_et(mo_elem: ET.Element) -> ManagedObjectType:  # noqa: C901
    """Build ManagedObjectType from ET managedObject element."""
    params: list[ParameterType] = []
    operation_val: str | None = None
    for child in mo_elem:
        local = _local_tag(child)
        if local == "parameter":
            pname = pnew = pprev = ""
            for sub in child:
                lsub = _local_tag(sub)
                if lsub == "parameterName":
                    pname = _elem_text(sub)
                elif lsub == "newValue":
                    pnew = _elem_text(sub)
                elif lsub == "prevValue":
                    pprev = _elem_text(sub)
            params.append(
                ParameterType(
                    parameter_name=pname,
                    new_value=pnew or None,
                    prev_value=pprev or None,
                )
            )
        elif local == "operation":
            operation_val = _elem_text(child) or None
    # Attributes: ET uses local names in attrib when no ns
    class_val = mo_elem.get("class")
    dist_val = mo_elem.get("distName")
    return ManagedObjectType(
        operation=operation_val,
        parameter=params,
        class_value=class_val,
        dist_name=dist_val,
    )


def _parse_envelope_from_et(env_elem: ET.Element) -> Envelope | None:  # noqa: C901
    """Build Envelope from ET element when xsdata fails (e.g. primitive node error).
    Only parses Body content needed for managedObject (parValueChangeInd, modifyParameterReq).
    """
    body_elem = None
    for child in env_elem:
        if _local_tag(child) == "Body":
            body_elem = child
            break
    if body_elem is None:
        return None
    par_value_change_ind = None
    module_ready_ind = None
    modify_parameter_req = None
    for body_child in body_elem:
        local = _local_tag(body_child)
        if local == "parValueChangeInd":
            managed: list[ManagedObjectType] = []
            for mo in body_child:
                if _local_tag(mo) == "managedObject":
                    managed.append(_parse_managed_object_from_et(mo))
            par_value_change_ind = ParValueChangeIndType(
                managed_object=managed,
                source=None,
                status=None,
            )
        elif local == "moduleReadyInd":
            bld = None
            for sub in body_child:
                if _local_tag(sub) == "bldVersion":
                    bld = _elem_text(sub) or None
                    break
            module_ready_ind = ModuleReadyIndType(bld_version=bld)
        elif local == "modifyParameterReq":
            managed = []
            for mo in body_child:
                if _local_tag(mo) == "managedObject":
                    managed.append(_parse_managed_object_from_et(mo))
            modify_parameter_req = ModifyParameterReqType(managed_object=managed)
    body = BodyType(
        par_value_change_ind=par_value_change_ind,
        module_ready_ind=module_ready_ind,
        modify_parameter_req=modify_parameter_req,
    )
    return Envelope(header=None, body=body)


def _body_tag_and_flat_from_body(body: BodyType) -> tuple[str, dict[str, dict[str, str]], dict[str, str]]:  # noqa: C901
    """Build body_tag, params (name -> {newValue, prevValue}), flat (field -> value) from Body."""
    body_tag = ""
    params: dict[str, dict[str, str]] = {}
    flat: dict[str, str] = {}

    if body.par_value_change_ind is not None:
        pvc = body.par_value_change_ind
        body_tag = "parValueChangeInd"
        if pvc.source is not None:
            flat["source"] = pvc.source
        if pvc.status is not None:
            flat["status"] = pvc.status
        for mo in pvc.managed_object:
            _add_managed_object_params(mo, params)

    elif body.module_ready_ind is not None:
        mri = body.module_ready_ind
        body_tag = "moduleReadyInd"
        if mri.bld_version is not None:
            flat["bldVersion"] = mri.bld_version

    elif body.modify_parameter_req is not None:
        mpr = body.modify_parameter_req
        body_tag = "modifyParameterReq"
        for mo in mpr.managed_object:
            _add_managed_object_params(mo, params)

    return body_tag, params, flat


def _add_managed_object_params(mo: ManagedObjectType, params: dict[str, dict[str, str]]) -> None:
    for p in mo.parameter:
        name = p.parameter_name or ""
        if name:
            params[name] = {
                "newValue": p.new_value or "",
                "prevValue": p.prev_value or "",
            }


def get_header_from_envelope(envelope: Envelope | None) -> HeaderType | None:
    """Header from parsed Envelope."""
    if envelope is None:
        return None
    return envelope.header


def get_body_from_envelope(envelope: Envelope | None) -> BodyType | None:
    """Body from parsed Envelope."""
    if envelope is None:
        return None
    return envelope.body


def get_managed_objects_from_envelope(envelope: Envelope | None) -> list[ManagedObjectType]:
    """All managedObject instances from Envelope body (parValueChangeInd + modifyParameterReq)."""
    if envelope is None or envelope.body is None:
        return []
    out: list[ManagedObjectType] = []
    body = envelope.body
    if body.par_value_change_ind is not None:
        out.extend(body.par_value_change_ind.managed_object)
    if body.modify_parameter_req is not None:
        out.extend(body.modify_parameter_req.managed_object)
    return out


def matches_param_transition(
    managed_object: ManagedObjectType,
    operation_name: str,
    parameter_name: str,
    prev_value: str,
    new_value: str,
) -> bool:
    """True if managedObject has operation_name and param parameter_name with prev_value -> new_value.

    Example:
        matches_param_transition(
            mo,
            operation_name="update_parm",
            parameter_name="state",
            prev_value="BUSY",
            new_value="READY",
        )
    """
    if (managed_object.operation or "") != operation_name:
        return False
    for p in managed_object.parameter:
        if (p.parameter_name or "") == parameter_name:
            nv = (p.new_value or "").strip()
            pv = (p.prev_value or "").strip()
            if nv == new_value and pv == prev_value:
                return True
    return False


class SOAPRecord:
    """
    Single SOAP record: timestamp + parsed Envelope (ru_soap).
    Flat: .get(name), .get_prev(name), .body_tag, .parameters(), .keys(), .as_dict().
    Typed: .header(), .body(), .managed_objects(), .envelope().
    """

    def __init__(self, timestamp_str: str | None, envelope: Envelope | None):
        self._envelope = envelope
        self._timestamp_str = timestamp_str or ""
        self._timestamp_dt: datetime | None = None
        self._body_tag = ""
        self._params: dict[str, dict[str, str]] = {}
        self._flat: dict[str, str] = {}
        self._parsed = False

    def _ensure_parsed(self) -> None:
        if self._parsed:
            return
        self._parsed = True
        if self._timestamp_str:
            try:
                self._timestamp_dt = datetime.fromisoformat(
                    self._timestamp_str.replace("Z", "+00:00")
                )
            except (ValueError, TypeError):
                self._timestamp_dt = None
        if self._envelope is not None and self._envelope.body is not None:
            self._body_tag, self._params, self._flat = _body_tag_and_flat_from_body(
                self._envelope.body
            )

    @property
    def timestamp(self) -> datetime | None:
        """Record timestamp as datetime (UTC when string ends with 'Z')."""
        self._ensure_parsed()
        return self._timestamp_dt

    @property
    def timestamp_str(self) -> str:
        """Timestamp as raw string."""
        return self._timestamp_str

    @property
    def body_tag(self) -> str:
        """Root element in Body: parValueChangeInd, moduleReadyInd, modifyParameterReq."""
        self._ensure_parsed()
        return self._body_tag

    def get(self, name: str, default: str | None = None) -> str:
        """Parameter value (newValue) or Body field (e.g. bldVersion, source)."""
        self._ensure_parsed()
        if name in self._params:
            return self._params[name].get("newValue", "") or (default or "")
        return self._flat.get(name, default or "")

    def get_prev(self, name: str, default: str | None = None) -> str:
        """Previous parameter value (prevValue)."""
        self._ensure_parsed()
        if name in self._params:
            return self._params[name].get("prevValue", "") or (default or "")
        return default or ""

    def __getitem__(self, name: str) -> str:
        val = self.get(name)
        if val == "" and name not in self._params and name not in self._flat:
            raise KeyError(name)
        return val

    def __contains__(self, name: str) -> bool:
        self._ensure_parsed()
        return name in self._params or name in self._flat

    def parameters(self) -> dict[str, dict[str, str]]:
        """Dict: parameter name -> {'newValue': ..., 'prevValue': ...}."""
        self._ensure_parsed()
        return dict(self._params)

    def keys(self) -> set[str]:
        """All keys (parameters and Body fields)."""
        self._ensure_parsed()
        return set(self._params) | set(self._flat)

    def as_dict(self) -> dict[str, str]:
        """Flat dict: key -> value."""
        self._ensure_parsed()
        out = dict(self._flat)
        for k, v in self._params.items():
            out[k] = v.get("newValue", "")
        return out

    def envelope(self) -> Envelope | None:
        """Parsed Envelope (ru_soap.Envelope)."""
        return self._envelope

    def header(self) -> HeaderType | None:
        """Header (ru_soap.HeaderType). Use .from_value for XML 'from' (Python keyword)."""
        return get_header_from_envelope(self._envelope)

    def body(self) -> BodyType | None:
        """Body (ru_soap.BodyType)."""
        return get_body_from_envelope(self._envelope)

    def managed_objects(self) -> list[ManagedObjectType]:
        """All managedObject instances in this record."""
        return get_managed_objects_from_envelope(self._envelope)


class SOAPParser:
    """
    Parser for SOAP trace files (SOAPMessageTrace).
    Sequence of <UTC-Timestamp> + <SOAP-ENV:Envelope>. Each Envelope parsed with xsdata (ru_soap).
    """

    def __init__(self, file_path: str | Path):
        self.file_path = Path(file_path)

    def parse(self) -> list[SOAPRecord]:
        """Parse the whole file and return list of records."""
        return list(self.records())

    def records(self):  # noqa: C901
        """Yield SOAPRecord one by one; each Envelope parsed with xsdata (ru_soap)."""
        with open(self.file_path, "rb") as f:
            tree = ET.parse(f)
        root = tree.getroot()
        if root is None:
            return
        children = list(root)
        i = 0
        while i < len(children):
            elem = children[i]
            tag = elem.tag.split("}", 1)[-1] if elem.tag and "}" in elem.tag else (elem.tag or "")
            if "Timestamp" in tag or tag == "UTC-Timestamp":
                ts = (elem.text or "").strip()
                i += 1
                envelope = None
                if i < len(children):
                    env_elem = children[i]
                    env_tag = env_elem.tag.split("}", 1)[-1] if env_elem.tag and "}" in env_elem.tag else (env_elem.tag or "")
                    if "Envelope" in env_tag:
                        header_obj = None
                        for ch in list(env_elem):
                            if _local_tag(ch) == "Header":
                                header_obj = _parse_header_from_et(ch)
                                break
                        _strip_header_from_envelope_element(env_elem)
                        xml_str = ET.tostring(env_elem, encoding="unicode", method="xml")
                        try:
                            envelope = _xsdata_parser.from_string(xml_str, Envelope)
                        except XmlContextError:
                            envelope = _parse_envelope_from_et(env_elem)
                        if header_obj is not None and envelope is not None:
                            envelope.header = header_obj
                        yield SOAPRecord(ts, envelope)
                        i += 1
                        continue
                yield SOAPRecord(ts, envelope)
                continue
            if "Envelope" in tag:
                header_obj = None
                for ch in list(elem):
                    if _local_tag(ch) == "Header":
                        header_obj = _parse_header_from_et(ch)
                        break
                _strip_header_from_envelope_element(elem)
                xml_str = ET.tostring(elem, encoding="unicode", method="xml")
                try:
                    envelope = _xsdata_parser.from_string(xml_str, Envelope)
                except XmlContextError:
                    envelope = _parse_envelope_from_et(elem)
                if header_obj is not None and envelope is not None:
                    envelope.header = header_obj
                yield SOAPRecord(None, envelope)
            i += 1
